public class MaxMinDemo {
    public static void main(String[] args) {
        int[] arr = {45, 12, 89, 33, 67, 5, 91, 28};

        int max = arr[0], maxIndex = 0;
        int min = arr[0], minIndex = 0;
        for (int i = 1; i < arr.length; i++) {
